package org.millenaire.common.utilities;import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;public class Point{public static Map<BlockPos,BlockState> cells=new HashMap<>();public BlockPos pos;public Point(int x,int y,int z){pos=new BlockPos(x,y,z);}public BlockState getBlockActualState(Level ignored){return cells.getOrDefault(pos,Blocks.AIR.defaultBlockState());}public Block getBlock(Level ignored){return getBlockActualState(ignored).getBlock();}public Point getRelative(double x,double y,double z){return new Point(pos.getX()+(int)x,pos.getY()+(int)y,pos.getZ()+(int)z);}public double distanceTo(net.minecraft.world.entity.Entity e){return pos.distSqr(net.minecraft.core.BlockPos.ZERO);}public double distanceTo(Point p){return Math.sqrt(pos.distSqr(p.pos));}public Point getBelow(){return getRelative(0,-1,0);}public Point getAbove(){return getRelative(0,1,0);}}